begin
for q in select * from jsonb_array_elements(d) loop
  insert into public.questionnaires (slug,name,domain,instructions,scored,sort)
  values (q->>'slug',q->>'name',q->>'domain',q->>'instr',(q->>'scored')::boolean,(q->>'sort')::int) returning id into qid;
  p := 0;
  for it in select * from jsonb_array_elements(q->'items') loop
    p := p + 1;
    insert into public.questions (questionnaire_id,position,text,kind,options,scored,alert_if_gt)
    values (qid,p,it->>'t',(it->>'k')::public.tipo_pergunta,it->'o',(it->>'s')::boolean,(it->>'a')::numeric);
  end loop;
  for b in select * from jsonb_array_elements(q->'bands') loop
    insert into public.scoring_bands (questionnaire_id,min_score,max_score,label,level)
    values (qid,(b->>0)::numeric,(b->>1)::numeric,b->>2,(b->>3)::public.nivel_faixa);
  end loop;
end loop;
end $seed$;
